response.value:
Para automatizar esta extracción con Playwright en Node.js, he preparado un script que sigue los pasos para seleccionar los filtros (Comprar -> Piso -> Hendaye), hacer clic en buscar y extraer los resultados mientras recorre las páginas que haya disponibles.

Aquí tienes el script completo en Node.js que realiza esta tarea y guarda los resultados como JSON. Este script se puede ejecutar en modo *headless*.

### Código del Script (Playwright + Node.js)

```javascript
const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
    // Iniciar el navegador. Cambiar headless: false si quieres ver el proceso visualmente.
    const browser = await chromium.launch({ headless: true });
    const context = await browser.newContext();
    const page = await context.newPage();

    console.log("Navegando a Inmobiliaria Iparralde...");
    await page.goto('https://inmobiliariaiparralde.com/', { waitUntil: 'domcontentloaded' });

    // 1. Asegurarnos de estar en la pestaña de 'Comprar' (por defecto suele estar, pero aseguramos)
    // El formulario tiene selects que usan bibliotecas de estilo (ej. Select2 o Bootstrap select)
    // Vamos a interactuar con ellos u ocultos.

    // Primero, vamos a intentar forzar los valores en los campos ocultos o usar la UI si es necesario.
    // Usaremos evaluate para forzar la búsqueda de forma segura si la UI construida encima (Select2) da problemas en modo automático.
    await page.evaluate(() => {
        // En muchos buscadores inmobiliarios, existen los "select" ocultos dentro del formulario principal.
        const typeSelect = document.querySelector('select[name="typ"]'); // O nombre similar como 'type', 'id_tipo_inmueble'
        const citySelect = document.querySelector('select[name="loc"]'); // O 'location', 'id_poblacion'

        if (typeSelect) {
            // Buscamos la opción de Piso y la seleccionamos
            const optionPiso = Array.from(typeSelect.options).find(opt => opt.text.toLowerCase().includes('piso'));
            if(optionPiso) typeSelect.value = optionPiso.value;
        }

        if (citySelect) {
            // Buscamos la opción de Hendaye
            const optionHendaye = Array.from(citySelect.options).find(opt => opt.text.toLowerCase().includes('hendaye'));
            if(optionHendaye) citySelect.value = optionHendaye.value;
        }
    });

    // Como alternativa, buscamos la interacción UI. Buscamos el contenedor del formulario de búsqueda y los desplegables.
    // Según tu imagen, hacemos clic para abrir las listas desplegables. 
    try {
        console.log("Aplicando filtros: Piso, Hendaye...");
        // Buscamos los textos en la pantalla para abrir los combo boxes y elegir las opciones (manejo de select personalizados)
        // XPath aproxima a los placeholders visualizados ("Tipo de Inmueble", "Municipio", o sus ítems)
        await page.locator('text=Tipo de inmueble').click({ timeout: 2000 }).catch(()=>null);
        await page.locator('text=Piso').first().click({ timeout: 2000 }).catch(()=>null);

        await page.locator('text=Municipio').click({ timeout: 2000 }).catch(()=>null);
        await page.locator('ul >> text=Hendaye').first().click({ timeout: 2000 }).catch(()=>null);
    } catch (e) {
        console.log("Ajustando filtros mediante URL/JS si UI estricto falló...", e.message);
    }

    // 2. Hacer clic en el botón de búsqueda rojo (icono de lupa)
    // Normalmente es un botón rojo brillante (.btn-search, o input type=submit) dentro del banner de búsqueda
    await Promise.all([
        page.waitForNavigation({ waitUntil: 'networkidle' }), // Esperamos a que cargue la lista tras clickear
        page.locator('form button[type="submit"], form .btn-primary').first().click()
    ]);

    console.log("Búsqueda iniciada, recopilando resultados...");

    const allResults = [];
    let hasNextPage = true;

    // 3. Iterar por la lista y la paginación
    while (hasNextPage) {
        // Extraemos los bloques de anuncios en la página actual
        // Nos basamos en clases típicas (listing, property-item, card, etc.)
        const properties = await page.evaluate(() => {
            const data = [];

            // Reemplaza '.property-listing' o '.card' con el selector real tras inspeccionar el grid principal
            const items = document.querySelectorAll('.property-item, .listing-card, article'); 
            const timestamp = new Date().toISOString();

            items.forEach((item) => {
                const titleNode = item.querySelector('h2, h3, .title');
                const priceNode = item.querySelector('.price');
                const locNode = item.querySelector('.location, .address');
                const linkNode = item.querySelector('a');

                const title = titleNode ? titleNode.innerText.trim() : null;
                const price = priceNode ? priceNode.innerText.trim() : null;
                const location = locNode ? locNode.innerText.trim() : null;
                const detailUrl = linkNode ? linkNode.href : null;

                // Extraer el ID único basado en el segmento de la URL (Ej: /inmueble/piso-hendaye-12345 -> 12345)
                const stableId = detailUrl ? detailUrl.split('-').pop().replace(/[^0-9]/g, '') : null;

                if (title && detailUrl) { // Sólo si parece válido
                    data.push({
                        id: stableId,
                        title,
                        price,
                        location,
                        detailUrl,
                        scrapedAt: timestamp
                    });
                }
            });
            return data;
        });

        allResults.push(...properties);
        console.log(`Extraídas ${properties.length} propiedades de esta página.`);

        // 4. Buscar botón de "Página siguiente", si no hay, romper ciclo.
        hasNextPage = await page.evaluate(() => {
            const nextBtn = document.querySelector('.pagination .next, a.next-page, a[rel="next"]');
            if (nextBtn && !nextBtn.classList.contains('disabled')) {
                nextBtn.click();
                return true;
            }
            return false;
        });

        if (hasNextPage) {
            // Si hacemos clic en 'next', esperamos que la red se estabilice cargando nuevos datos
            await page.waitForLoadState('networkidle');
        }
    }

    console.log(`Proceso completado. Un total de ${allResults.length} resultados encontrados.`);

    // Mostramos la salida por consola en formato tabla y JSON
    console.table(allResults);

    // Guardar los resultados en formato JSON
    fs.writeFileSync('inmuebles_hendaye.json', JSON.stringify(allResults, null, 2), 'utf8');
    console.log("Datos exportados correctamente en inmuebles_hendaye.json");

    await browser.close();
})();
```

### Cómo ejecutarlo para probar:
Para ejecutar esto, necesitarás instalar las dependencias localmente abrir un terminal en tu carpeta `PROYECTO_iparralde` y ejecutar:

```bash
npm init -y
npm install playwright
node scraper.js
```

