() => {
  const form = document.querySelector('form.findus');
  if (!form) return null;
  const getOptions = (name) => {
    const sel = form.querySelector(`select[name="${name}"]`);
    if (!sel) return null;
    return Array.from(sel.options).map(o => ({ value: o.value, text: (o.textContent || '').trim() })).slice(0, 120);
  };

  const tabs = Array.from(document.querySelectorAll('.sale-rent li, .sale-rent a, [data-venta], [data-alquiler], .rent, .buy, .alquilar, .comprar')).map(el => ({
    tag: el.tagName,
    text: (el.textContent || '').trim(),
    className: el.className,
    href: el.getAttribute('href'),
    dataModalidad: el.getAttribute('data-modalidad'),
    dataValue: el.getAttribute('data-value'),
    onclick: el.getAttribute('onclick')
  })).filter(x => x.text);

  const modalidadInput = form.querySelector('input[name="modalidad"]');
  const busquedaInput = form.querySelector('input[name="busqueda"]');

  return {
    action: form.getAttribute('action'),
    hidden: {
      modalidad: modalidadInput ? modalidadInput.value : null,
      busqueda: busquedaInput ? busquedaInput.value : null,
    },
    tipoOptions: getOptions('tipoInmueble[]'),
    municipioOptions: getOptions('municipio[]'),
    tabs: tabs.slice(0, 40)
  };
}

